DROP TABLE IF EXISTS `strategy_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `strategy_history` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(10) unsigned NOT NULL,
  `strategy_id` varchar(50) NOT NULL,
  `discount_applied` decimal(5,2) DEFAULT 0.00,
  `original_price` decimal(10,2) DEFAULT NULL,
  `discounted_price` decimal(10,2) DEFAULT NULL,
  `status` enum('applied','completed','cancelled') NOT NULL DEFAULT 'applied',
  `started_at` datetime NOT NULL DEFAULT current_timestamp(),
  `ended_at` datetime DEFAULT NULL,
  `units_sold_during` int(11) DEFAULT 0,
  `revenue_during` decimal(12,2) DEFAULT 0.00,
