DROP TABLE IF EXISTS `strategy_templates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `strategy_templates` (
  `id` varchar(50) NOT NULL,
  `name` varchar(150) NOT NULL,
  `priority` int(11) NOT NULL DEFAULT 1,
  `discount_min` decimal(5,2) NOT NULL DEFAULT 0.00,
  `discount_max` decimal(5,2) NOT NULL DEFAULT 40.00,
  `duration_days` int(11) NOT NULL DEFAULT 7,
  `conditions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`conditions`)),
  `risk_levels` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '[]' CHECK (json_valid(`risk_levels`)),
  `expected_impact_min` int(11) NOT NULL DEFAULT 0,
  `expected_impact_max` int(11) NOT NULL DEFAULT 0,
  `implementation_steps` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`implementation_steps`)),
  `description` text DEFAULT NULL,
  `why_it_works` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
